(()=>{
 const english=document.documentElement.lang==='en',tr=(a,b)=>english?b:a;
 const base='https://greengo-uob-commute.dawsen1208.workers.dev';
 const panel=document.createElement('section');panel.className='planner';panel.id='live-transit';
 panel.innerHTML=`<p class="eyebrow">TFWM / BUS INFORMATION</p><h2>${tr('查询公交站与预计到站','Find bus stops and arrival predictions')}</h2><p>${tr('此处查询实际接口，独立于上方模拟通勤计算。选择正确的站点及行驶方向；尚未自动计算公交全程或验证是否到达校园。','This panel queries the provider separately from the simulated planner above. Check the stop and direction; full bus journeys and campus connections are not yet calculated.')}</p><form id="stop-search" class="route-card"><label>${tr('站点名称或地区','Stop name or area')}<input id="stop-query" value="Selly Oak" minlength="2" maxlength="80" required></label><button class="primary">${tr('搜索站点','Search stops')}</button></form><p id="transit-state" role="status"></p><div id="stop-results"></div><div id="arrival-results" aria-live="polite"></div>`;
 document.querySelector('#map').before(panel);
 const state=document.getElementById('transit-state'),results=document.getElementById('stop-results'),arrivals=document.getElementById('arrival-results');
 async function get(path){const r=await fetch(base+path,{signal:AbortSignal.timeout(15000)});const j=await r.json();if(!r.ok)throw new Error(j.error||'unavailable');return j;}
 function message(error){state.textContent=tr('实时数据不可用：','Live information unavailable: ')+(error.message==='credentials_not_configured'?tr('请检查后端 Secrets。','check backend Secrets.'):error.message==='provider_auth_failed'?tr('提供商拒绝凭证，请检查授权。','provider rejected credentials; check authorization.'):tr('请稍后重试，无法据此判断班次是否正常。','try again later; service status cannot be inferred.'));}
 document.getElementById('stop-search').onsubmit=async e=>{e.preventDefault();results.replaceChildren();arrivals.replaceChildren();state.textContent=tr('正在查询 TfWM…','Querying TfWM…');try{const data=await get('/api/stops?q='+encodeURIComponent(document.getElementById('stop-query').value.trim()));state.textContent=tr('来源 TfWM · 获取时间 ','Source TfWM · Retrieved ')+new Date(data.fetchedAt).toLocaleString(english?'en-GB':'zh-CN',{timeZone:'Europe/London'})+tr('（英国时间）',' (UK time)');if(!data.items.length){results.textContent=tr('没有匹配站点，请更换搜索词。','No matching stops. Try another search.');return;}data.items.forEach(stop=>{const b=document.createElement('button');b.className='outline';b.style.margin='6px';b.textContent=stop.name+' · '+stop.id;b.onclick=()=>load(stop);results.append(b);});}catch(error){message(error);}};
 async function load(stop){arrivals.replaceChildren();state.textContent=tr('正在获取到站预测…','Loading arrival predictions…');try{const data=await get('/api/arrivals?stopId='+encodeURIComponent(stop.id));state.textContent=stop.name+' · TfWM · '+new Date(data.fetchedAt).toLocaleString(english?'en-GB':'zh-CN',{timeZone:'Europe/London'});if(!data.items.length){arrivals.textContent=tr('暂无到站预测。这不代表停运或正常运行。','No predictions available. This does not establish cancellation or normal operation.');return;}data.items.forEach(a=>{const p=document.createElement('p');const date=new Date(a.expectedArrival);p.textContent=a.line+' → '+a.destination+' · '+(!Number.isNaN(date.valueOf())?date.toLocaleTimeString('en-GB',{timeZone:'Europe/London'}):tr('暂无预计时间','No predicted time'));arrivals.append(p);});}catch(error){message(error);}}
})();
